def embedded_texture(name):
    _data = base64.b64decode(IMAGES[name])
    _img = _PILImage.open(io.BytesIO(_data)).convert('RGBA')
    _w, _h = _img.size
    _tex = _Texture.create(size=(_w, _h), colorfmt='rgba')
    _tex.blit_buffer(_img.tobytes(), colorfmt='rgba', bufferfmt='ubyte')
    _tex.flip_vertical()
    return _tex


def EmbeddedImage(name, **kwargs):
    return _Image(texture=embedded_texture(name), **kwargs)


