class MaterialDropdownOption(Button):
    def __init__(self, **kwargs):
        super().__init__(
            background_normal='',
            background_down='',
            background_color=(1, 1, 1, 1),
            color=(0.15, 0.2, 0.28, 1),
            font_size=18,
            **kwargs
        )


class MaterialDropdown(Button):
    def __init__(self, values=(), **kwargs):
        kwargs.setdefault('background_normal', '')
        kwargs.setdefault('background_down', '')
        kwargs.setdefault('background_color', (1, 1, 1, 1))
        kwargs.setdefault('color', MATERIAL_PLACEHOLDER_COLOR)
        kwargs.setdefault('halign', 'left')
        kwargs.setdefault('valign', 'middle')
        kwargs.setdefault('padding', [12, 0])
        super().__init__(**kwargs)
        self.values = list(values)
        self.dropdown = DropDown(auto_width=False)
        self._dropdown_open = False
        self.dropdown.bind(on_select=self.select_value)
        self.dropdown.bind(on_dismiss=self.dropdown_dismissed)
        self.bind(on_release=self.toggle_dropdown)
        self.bind(size=self.update_dropdown_width)

        for value in self.values:
            option = MaterialDropdownOption(
                text=value,
                size_hint_y=None,
                height=44
            )
            option.bind(
                on_release=lambda button: self.dropdown.select(button.text)
            )
            self.dropdown.add_widget(option)

        with self.canvas.before:
            Color(1, 1, 1, 1)
            self.field_background = RoundedRectangle(
                pos=self.pos,
                size=self.size,
                radius=[5]
            )
        with self.canvas.after:
            Color(*INPUT_BORDER_COLOR)
            self.field_border = Line(points=[], close=True, width=1)
            Color(0.28, 0.34, 0.42, 1)
            self.chevron = Line(points=[], width=2, cap='round', joint='round')

        self._update_field_graphics = Clock.create_trigger(
            self.update_field_graphics,
            0
        )
        self.bind(pos=self._update_field_graphics, size=self._update_field_graphics)
        self.bind(size=self.update_text_size)
        self.bind(text=self.update_text_color)
        self._update_field_graphics()
        self.update_text_size()
        self.update_text_color()

    def toggle_dropdown(self, *args):
        self.update_field_graphics()
        if self._dropdown_open:
            self.dropdown.dismiss()
        else:
            self.dropdown.width = self.width
            self.dropdown.open(self)
            self._dropdown_open = True

    def update_dropdown_width(self, *args):
        if self._dropdown_open:
            self.dropdown.width = self.width

    def dropdown_dismissed(self, *args):
        self._dropdown_open = False

    def update_text_size(self, *args):
        self.text_size = (max(0, self.width - 36), self.height)

    def select_value(self, dropdown, value):
        self.text = value

    def update_field_graphics(self, *args):
        self.field_background.pos = self.pos
    
    def update_dropdown_width(self, *args):
        if self._dropdown_open:
            self.dropdown.width = self.width

    def dropdown_dismissed(self, *args):
        self._dropdown_open = False

    def update_text_size(self, *args):
        self.text_size = (max(0, self.width - 36), self.height)

    def select_value(self, dropdown, value):
        self.text = value

    def update_field_graphics(self, *args):
        self.field_background.pos = self.pos
        self.field_background.size = self.size
        self.field_border.points = [
            self.x, self.y,
            self.right, self.y,
            self.right, self.top,
            self.x, self.top
        ]
        center_x = self.right - 20
        center_y = self.center_y
        self.chevron.points = [
            center_x - 6, center_y + 3,
            center_x, center_y - 3,
            center_x + 6, center_y + 3
        ]

    def update_text_color(self, *args):
        self.color = (
            MATERIAL_PLACEHOLDER_COLOR
            if self.text == "Select material..."
            else (0.15, 0.2, 0.28, 1)
        )



