def style_tool_screen(screen, layout, title, accent, subtitle, title_in_content=False):
    with screen.canvas.before:
        Color(*tool_background_color(accent))
        screen.background = Rectangle(pos=screen.pos, size=screen.size)
    screen.bind(
        pos=lambda widget, value: setattr(screen.background, 'pos', value),
        size=lambda widget, value: setattr(screen.background, 'size', value)
    )
    if isinstance(layout, BoxLayout):
        layout.padding = 20
        layout.spacing = 10

    for widget in list(layout.children):
        if isinstance(widget, Button) and widget.text == "Back to Home":
            layout.remove_widget(widget)
            continue
        if isinstance(widget, MaterialDropdown):
            widget.background_normal = ''
            widget.background_down = ''
            widget.background_color = (1, 1, 1, 1)
            widget.update_text_color()
        elif isinstance(widget, Button):
            is_back_button = widget.text == "Back to Home"
            widget.size_hint = (0.72, None)
            widget.height = 44
            widget.pos_hint = {'center_x': 0.5}
            widget.background_normal = ''
            widget.background_down = ''
            widget.background_color = (
                (0.88, 0.91, 0.95, 1) if is_back_button else accent
            )
            widget.color = (0.15, 0.2, 0.28, 1) if is_back_button else (1, 1, 1, 1)
        elif isinstance(widget, TextInput):
            widget.size_hint_y = None
            widget.height = 46
            widget.background_normal = ''
            widget.background_active = ''
            widget.background_color = (1, 1, 1, 1)
            widget.foreground_color = (0.15, 0.2, 0.28, 1)
            widget.cursor_color = accent
            widget.padding = [12, 12]
        elif isinstance(widget, Label):
            widget.color = (0.15, 0.2, 0.28, 1)

    result_label = getattr(screen, "result_label", None)
    if result_label is not None:
        result_label.color = accent
        result_label.bold = True

    add_tool_header(screen, layout, title, accent, subtitle, title_in_content)


def add_tool_header(screen, layout, title, accent, subtitle, title_in_content=False):
    heading = FloatLayout(
        size_hint=(1, None),
        height=64,
        pos_hint={'x': 0, 'top': 1}
    )
    back_button = Button(
            text="",
            size_hint=(None, None),
            size=(44, 44),
            pos_hint={'x': 0, 'top': 1},
            background_normal='',
            background_down='',
            background_color=(0, 0, 0, 0)
        )
    with back_button.canvas.before:
            Color(1, 1, 1, 0.96)
            back_button.background_shape = RoundedRectangle(
                pos=back_button.pos,
                size=back_button.size,
                radius=[14]
            )
    with back_button.canvas.after:
            Color(*accent)
            back_button.arrow = Line(points=[], width=2.4, cap='round', joint='round')
    
    def update_arrow(widget, *args):
            x, y = widget.pos
            width, height = widget.size
            widget.background_shape.pos = widget.pos
            widget.background_shape.size = widget.size
            widget.arrow.points = [
                x + width * 0.67, y + height * 0.5,
                x + width * 0.33, y + height * 0.5,
                x + width * 0.52, y + height * 0.7,
                x + width * 0.33, y + height * 0.5,
                x + width * 0.52, y + height * 0.3,
            ]
    
    back_button.bind(pos=update_arrow, size=update_arrow)
    update_arrow(back_button)
    back_button.bind(on_press=lambda instance: setattr(screen.manager, 'current', 'home'))
    
    heading.add_widget(back_button)
    if not title_in_content:
            title_layout = BoxLayout(
                orientation='vertical',
                spacing=1,
                size_hint=(0.82, 1),
                pos_hint={'right': 1, 'top': 1}
            )
            title_label = Label(
                text=f"[b]{title}[/b]",
                markup=True,
                font_size=21,
                color=accent,
                halign='left',
                valign='middle'
            )
            title_label.bind(size=title_label.setter('text_size'))
            subtitle_label = Label(
                text=subtitle,
                font_size=12,
                color=(0.38, 0.45, 0.55, 1),
                halign='left',
                valign='middle'
            )
            subtitle_label.bind(size=subtitle_label.setter('text_size'))
            title_layout.add_widget(title_label)
            title_layout.add_widget(subtitle_label)
            heading.add_widget(title_layout)
    layout.add_widget(heading, index=len(layout.children))


def add_calculator_section(content, title, accent, subtitle):
    section = BoxLayout(
        orientation='vertical',
        spacing=2,
        size_hint=(1, None),
        height=58
    )
    title_label = Label(
        text=f"[b]{title}[/b]",
        markup=True,
        font_size=21,
        color=accent,
        halign='center',
        valign='middle',
        size_hint=(1, None),
        height=32
    )
    title_label.bind(size=title_label.setter('text_size'))
    subtitle_label = Label(
        text=subtitle,
        font_size=12,
        color=(0.38, 0.45, 0.55, 1),
        halign='center',
        valign='middle',
         size_hint=(1, None),
        height=24
    )
    subtitle_label.bind(size=subtitle_label.setter('text_size'))
    section.add_widget(title_label)
    section.add_widget(subtitle_label)
    content.add_widget(section)


def tool_background_color(accent):
    tint_strength = 0.12
    return tuple(
        1 - tint_strength + channel * tint_strength
        for channel in accent[:3]
    ) + (1,)

def build_compact_calculator(screen, layout, fields, calculate_button, result_label,
                             title, accent, subtitle, rows=None, result_height=76,
                             button_text="Calculate"):
    """
    fields: either a flat list of (label, input) OR a list of rows,
            where each row is a list of (label, input) pairs.
    rows: optional explicit row grouping (overrides automatic grouping).
          Pass e.g. [[("A", inp1), ("B", inp2)], [("C", inp3)]].
    """
    
    if rows is None:
        
        if len(fields) <= 3:
            rows = [fields]
        else:
            
            rows = [fields[i:i + 3] for i in range(0, len(fields), 3)]

    rows_grid = GridLayout(
        cols=1,
        rows=len(rows),
        spacing=10,
        size_hint=(1, None),
        height=len(rows) * (92 + 10) - 10  
    )

    for row_fields in rows:
        row_grid = GridLayout(
            cols=len(row_fields),
            rows=1,
            spacing=8,
            size_hint=(1, None),
            height=92
        )
        for label_text, text_input in row_fields:
            text_input.size_hint = (1, None)
            text_input.height = 44
            text_input.background_normal = ''
            text_input.background_active = ''
            text_input.background_color = (1, 1, 1, 1)
            text_input.foreground_color = (0.15, 0.2, 0.28, 1)
            text_input.cursor_color = accent
            text_input.padding = [8, 10]

            field = BoxLayout(orientation='vertical', spacing=5)
            label = Label(
                text=label_text,
                font_size=13,
                color=(0.15, 0.2, 0.28, 1),
                size_hint=(1, None),
                height=40,
                halign='left',
                valign='middle'
            )
            label.bind(size=label.setter('text_size'))
            field.add_widget(label)
            field.add_widget(text_input)
            row_grid.add_widget(field)
        rows_grid.add_widget(row_grid)

    result_label.size_hint = (1, None)
    result_label.height = result_height
    result_label.halign = 'center'
    result_label.valign = 'middle'
    result_label.bind(size=result_label.setter('text_size'))

    calculate_button.text = button_text
    content = BoxLayout(
        orientation='vertical',
        spacing=14,
        size_hint=(1, None)
    )
    add_calculator_section(content, title, accent, subtitle)
    content.add_widget(rows_grid)
    content.add_widget(result_label)
    content.add_widget(calculate_button)
    content.bind(minimum_height=content.setter('height'))

    centered_content = AnchorLayout(
        anchor_x='center',
        anchor_y='center',
        padding=16
    )
    centered_content.add_widget(content)
    layout.add_widget(centered_content)

    style_tool_screen(screen, layout, title, accent, subtitle, title_in_content=True)

    calculate_button.size_hint = (0.55, None)
    calculate_button.height = 40
    calculate_button.pos_hint = {'center_x': 0.5}
    calculate_button.background_normal = ''
    calculate_button.background_down = ''
    calculate_button.background_color = accent
    calculate_button.color = (1, 1, 1, 1)


def increase_app_font_sizes(root, amount=4):
    def process_children(parent, children):
        for child in children:
            process_widget(child)

    def process_widget(widget):
        if getattr(widget, '_app_font_size_bumped', False):
            return
        widget._app_font_size_bumped = True

        font_size = getattr(widget, 'font_size', None)
        if isinstance(font_size, (int, float)):
            widget.font_size = font_size + amount

        if hasattr(widget, 'children'):
            widget.bind(children=process_children)
            for child in widget.children:
                process_widget(child)

    process_widget(root)


def create_labeled_field(label_text, text_input, label_height=30):
    """Helper: wraps a TextInput in a BoxLayout with a descriptive label above it."""
    field = BoxLayout(orientation='vertical', spacing=4)
    label = Label(
        text=label_text,
        font_size=13,
        size_hint=(1, None),
        height=label_height,
        halign='left',
        valign='middle',
        color=(0.15, 0.2, 0.28, 1)
    )
    label.bind(size=label.setter('text_size'))
    field.add_widget(label)
    field.add_widget(text_input)
    return field


def parse_optional_float(text):
    """Helper: returns float(text) or None if the text is blank."""
    text = text.strip()
    if text == "":
        return None
    return float(text)



