class AnimatedBlobScreen(Screen):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        with self.canvas.before:
            Color(0.96, 0.97, 0.99, 1)
            self.bg = Rectangle(size=self.size, pos=self.pos)
        self.bind(size=self.update_bg, pos=self.update_bg)
        self.blob_elapsed = 0
        self.blob_animation = None
        self.blobs = []
        blob_specs = [
            (0.12, 0.18, 0.055, TOOL_COLORS["heatloss"], 0.8, 1.1),
            (0.82, 0.22, 0.075, TOOL_COLORS["projectile"], 1.0, 0.7),
            (0.18, 0.72, 0.07, TOOL_COLORS["energy"], 0.7, 0.9),
            (0.87, 0.77, 0.05, TOOL_COLORS["newton"], 1.1, 0.8),
            (0.53, 0.12, 0.045, TOOL_COLORS["formula_sheet"], 0.9, 1.2),
            (0.48, 0.88, 0.06, TOOL_COLORS["kinematics"], 0.8, 0.75),
        ]
        with self.canvas.before:
            self.bg_color = Color(1, 1, 1, 1)
            for x, y, radius, color, speed_x, speed_y in blob_specs:
                tint = Color(color[0], color[1], color[2], 0.24)
                blob = Ellipse(pos=(0, 0), size=(0, 0))
                self.blobs.append({
                    "x": x,
                     "y": y,
                    "radius": radius,
                    "speed_x": speed_x,
                    "speed_y": speed_y,
                    "phase": len(self.blobs) * 1.05,
                    "tint": tint,
                    "shape": blob,
                })
        self.bind(size=self.update_blobs)
        self.update_blobs()

    def update_bg(self, *args):
        self.bg.size = self.size
        self.bg.pos = self.pos

    def update_blobs(self, *args):
        width, height = self.size
        scale = min(width, height)
        for blob in self.blobs:
            diameter = scale * blob["radius"]
            x = self.x + width * blob["x"] + math.sin(
                self.blob_elapsed * blob["speed_x"] + blob["phase"]
            ) * width * 0.055
            y = self.y + height * blob["y"] + math.cos(
                self.blob_elapsed * blob["speed_y"] + blob["phase"]
            ) * height * 0.035
            blob["shape"].size = (diameter, diameter)
            blob["shape"].pos = (x - diameter / 2, y - diameter / 2)

    def animate_blobs(self, dt):
        self.blob_elapsed += dt
        self.update_blobs()

    def on_pre_enter(self, *args):
        if self.blob_animation is None:
            self.blob_animation = Clock.schedule_interval(self.animate_blobs, 1 / 30)

    def on_leave(self, *args):
        if self.blob_animation is not None:
            self.blob_animation.cancel()
            self.blob_animation = None


class SplashScreen(AnimatedBlobScreen):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.bg.texture = embedded_texture("logo")

    def on_touch_down(self, touch):
        self.manager.current = "home"
        return True


class FunctionWidget(ButtonBehavior, BoxLayout):
    def __init__(self, icon_source, title, callback=None, **kwargs):
        super().__init__(orientation='vertical', size_hint=(0.7, 0.7), **kwargs)
        self.callback = callback
        self.icon = EmbeddedImage(icon_source, size_hint=(1, 0.6))
        self.label = Label(
            text=title,
            size_hint=(1, 0.4),
            halign='center',
            valign='middle',
            font_size=12,
        )
        self.label.bind(size=self.label.setter('text_size'))
        self.add_widget(self.icon)
        self.add_widget(self.label)

    def on_press(self):
        if self.callback:
            self.callback()



