class HomeOptionCard(ButtonBehavior, BoxLayout):
    def __init__(self, title, description, color, callback, **kwargs):
        super().__init__(
            orientation='horizontal',
            padding=[16, 8],
            size_hint=(1, None),
            height=84,
            **kwargs
        )
        self.callback = callback

        with self.canvas.before:
            Color(*color)
            self.card_background = RoundedRectangle(
                pos=self.pos,
                size=self.size,
                radius=[12]
            )
        self.bind(pos=self.update_background, size=self.update_background)

        text_column = BoxLayout(
            orientation='vertical',
            spacing=2,
            size_hint=(1, 1)
        )
        title_label = Label(
            text=f"[b]{title}[/b]",
            markup=True,
            font_size=18,
            color=(1, 1, 1, 1),
            halign='left',
            valign='middle',
            size_hint=(1, None),
            height=32
        )
        title_label.bind(size=title_label.setter('text_size'))

        description_label = Label(
            text=description,
            font_size=12,
            color=(0.92, 0.96, 1, 1),
            halign='left',
            valign='middle',
            size_hint=(1, 1)
        )
        description_label.bind(size=description_label.setter('text_size'))

        text_column.add_widget(title_label)
        text_column.add_widget(description_label)
        self.add_widget(text_column)

    def update_background(self, *args):
        self.card_background.pos = self.pos
        self.card_background.size = self.size

    def on_press(self):
        self.callback()


