class HeatLossCalculator(Screen):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        layout = FloatLayout()

        self.width_input = TextInput(multiline=False, input_filter='float')
        self.length_input = TextInput(multiline=False, input_filter='float')
        self.height_input = TextInput(multiline=False, input_filter='float')
        self.thickness_input = TextInput(multiline=False, input_filter='float')
        self.temp_input = TextInput(multiline=False, input_filter='float')
        self.q_input = TextInput(multiline=False, input_filter='float')

        self.material_input = MaterialDropdown(
            text='Select material...',
            values=list(MATERIALS.keys()),
            size_hint=(1, None),
            height=44
        )
        material_field = BoxLayout(
            orientation='vertical',
            spacing=5,
            size_hint=(1, None),
            height=90
        )
        material_label = Label(
            text="Wall Material",
            font_size=13,
            color=(0.15, 0.2, 0.28, 1),
            size_hint=(1, None),
            height=40,
            halign='left',
            valign='middle'
        )
        material_label.bind(size=material_label.setter('text_size'))
        material_field.add_widget(material_label)
        material_field.add_widget(self.material_input)

        self.calculate_btn = Button(text="Calculate Missing Value")
        self.calculate_btn.bind(on_press=self.calculate_heat_loss)

        self.result_label = Label(text="")

        self.add_widget(layout)


        def make_field(label_text, text_input):
            field = BoxLayout(
                orientation='vertical',
                spacing=5,
                size_hint=(1, None),
                height=90
            )
            label = Label(
                text=label_text,
                font_size=13,
                color=(0.15, 0.2, 0.28, 1),
                size_hint=(1, None),
                height=40,
                halign='left',
                valign='middle'
            )
            label.bind(size=label.setter('text_size'))

            text_input.size_hint = (1, None)
            text_input.height = 44
            text_input.background_normal = ''
            text_input.background_active = ''
            text_input.background_color = (1, 1, 1, 1)
            text_input.foreground_color = (0.15, 0.2, 0.28, 1)
            text_input.cursor_color = TOOL_COLORS["heatloss"]
            text_input.padding = [8, 10]

            field.add_widget(label)
            field.add_widget(text_input)
            return field

        parameter_grid = GridLayout(
            cols=3,
            rows=2,
            spacing=8,
            size_hint=(1, None),
            height=90 * 2 + 8
        )
        parameter_grid.add_widget(make_field("Width (m)", self.width_input))
        parameter_grid.add_widget(make_field("Length (m)", self.length_input))
        parameter_grid.add_widget(make_field("Height (m)\n(0/blank = slab)", self.height_input))
        # Row 2
        parameter_grid.add_widget(make_field("ΔT (°C)", self.temp_input))
        parameter_grid.add_widget(make_field("Thickness d (m)", self.thickness_input))
        parameter_grid.add_widget(make_field("Heat Loss Q (W)", self.q_input))

        content = BoxLayout(
            orientation='vertical',
            spacing=14,
            size_hint=(1, None)
        )
        add_calculator_section(
            content,
            "Heat Loss Calculator",
            TOOL_COLORS["heatloss"],
            "Solve for any single missing variable."
        )
        content.add_widget(parameter_grid)
        content.add_widget(material_field)
        content.add_widget(self.result_label)
        content.add_widget(self.calculate_btn)
        content.bind(minimum_height=content.setter('height'))

        centered_content = AnchorLayout(
            anchor_x='center',
            anchor_y='center',
            padding=16
        )
        centered_content.add_widget(content)
        layout.add_widget(centered_content)

        style_tool_screen(
            self, layout, "Heat Loss Calculator", TOOL_COLORS["heatloss"],
            "Solve for any single missing variable.", title_in_content=True
        )

        for inp in (self.width_input, self.length_input, self.height_input,
                    self.thickness_input, self.temp_input, self.q_input):
            inp.size_hint_y = None
            inp.height = 44
            inp.background_normal = ''
            inp.background_active = ''
            inp.background_color = (1, 1, 1, 1)
            inp.foreground_color = (0.15, 0.2, 0.28, 1)
            inp.cursor_color = TOOL_COLORS["heatloss"]
            inp.padding = [8, 10]

        self.result_label.size_hint = (1, None)
        self.result_label.height = 60
        self.result_label.halign = 'center'
        self.result_label.valign = 'middle'
        self.result_label.bind(size=self.result_label.setter('text_size'))
        self.result_label.color = TOOL_COLORS["heatloss"]
        self.result_label.bold = True

        self.calculate_btn.size_hint = (0.55, None)
        self.calculate_btn.height = 44
        self.calculate_btn.pos_hint = {'center_x': 0.5}
        self.calculate_btn.background_normal = ''
        self.calculate_btn.background_down = ''
        self.calculate_btn.background_color = TOOL_COLORS["heatloss"]
        self.calculate_btn.color = (1, 1, 1, 1)

    def calculate_heat_loss(self, instance):
        try:
            width = parse_optional_float(self.width_input.text)
            length = parse_optional_float(self.length_input.text)
            height = parse_optional_float(self.height_input.text) or 0.0
            thickness = parse_optional_float(self.thickness_input.text)
            temp_diff = parse_optional_float(self.temp_input.text)
            q = parse_optional_float(self.q_input.text)
            material = self.material_input.text.strip()

            if material not in MATERIALS:
                self.result_label.text = "⚠️ Invalid material! Choose from the list."
                return

            k = MATERIALS[material]

            if width is None or length is None:
                self.result_label.text = "⚠️ Need width and length to compute area."
                return

            if height > 0:
                area = 2 * (width * height + length * height)
            else:
                area = width * length

            missing = [name for name, val in [
                ("Q", q), ("ΔT", temp_diff), ("Thickness", thickness)
            ] if val is None]

            if len(missing) > 1:
                self.result_label.text = f"⚠️ Leave only ONE value blank.\nCurrently blank: {', '.join(missing)}"
                return
            if len(missing) == 0:
                self.result_label.text = "⚠️ Leave exactly one field blank to solve for it."
                return

            target = missing[0]

            if target == "Q":
                if not temp_diff or not thickness:
                    self.result_label.text = "⚠️ Need ΔT and thickness to solve for Q."
                    return
                q = k * area * temp_diff / thickness
                self.result_label.text = f"Solved Heat Loss Q: {q:.2f} W"
            elif target == "ΔT":
                if not q or not thickness:
                    self.result_label.text = "⚠️ Need Q and thickness to solve for ΔT."
                    return
                temp_diff = q * thickness / (k * area)
                self.result_label.text = f"Solved ΔT: {temp_diff:.2f} °C"
            elif target == "Thickness":
                if not q or not temp_diff:
                    self.result_label.text = "⚠️ Need Q and ΔT to solve for thickness."
                    return
                thickness = k * area * temp_diff / q
                self.result_label.text = f"Solved Thickness: {thickness:.3f} m"

        except ValueError:
            self.result_label.text = "⚠️ Please enter valid numbers."
        except ZeroDivisionError:
            self.result_label.text = "⚠️ Error: Division by zero. Check inputs."



class EnergyCalculator(Screen):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        layout = FloatLayout()

        self.power_input = TextInput(multiline=False, input_filter='float')
        self.time_input = TextInput(multiline=False, input_filter='float')
        self.energy_input = TextInput(multiline=False, input_filter='float')

        self.calculate_btn = Button(text="Calculate Missing Value")
        self.calculate_btn.bind(on_press=self.calculate_energy)
        self.result_label = Label(text="")

        self.add_widget(layout)
        build_compact_calculator(
            self,
            layout,
            [
                ("Power (W)", self.power_input),
                ("Time (h)", self.time_input),
                ("Energy (Wh)", self.energy_input),
            ],
            self.calculate_btn,
            self.result_label,
            "Energy Calculator",
            TOOL_COLORS["energy"],
            "Solve for Power, Time, or Energy."
        )

    def calculate_energy(self, instance):
        try:
            power = parse_optional_float(self.power_input.text)
            time = parse_optional_float(self.time_input.text)
            energy = parse_optional_float(self.energy_input.text)

            missing = [name for name, val in [
                ("Power", power), ("Time", time), ("Energy", energy)
            ] if val is None]

            if len(missing) > 1:
                self.result_label.text = f"⚠️ Leave only ONE value blank.\nCurrently blank: {', '.join(missing)}"
                return
            if len(missing) == 0:
                self.result_label.text = "⚠️ Leave exactly one field blank to solve for it."
                return

            target = missing[0]

            if target == "Energy":
                energy = power * time
                self.result_label.text = f"Solved Energy: {energy:.2f} Wh"
            elif target == "Power":
                if time == 0:
                    self.result_label.text = "⚠️ Time cannot be 0 when solving for Power."
                    return
                power = energy / time
                self.result_label.text = f"Solved Power: {power:.2f} W"
            elif target == "Time":
                if power == 0:
                    self.result_label.text = "⚠️ Power cannot be 0 when solving for Time."
                    return
                time = energy / power
                self.result_label.text = f"Solved Time: {time:.2f} h"

        except ValueError:
            self.result_label.text = "⚠️ Please enter valid numbers."



class ProjectileMotionScreen(Screen):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        layout = FloatLayout()

        self.velocity_input = TextInput(multiline=False, input_filter='float')
        self.angle_input = TextInput(multiline=False, input_filter='float')
        self.range_input = TextInput(multiline=False, input_filter='float')
        self.height_input = TextInput(multiline=False, input_filter='float')
        self.time_input = TextInput(multiline=False, input_filter='float')

        self.calculate_btn = Button(text="Calculate Missing Values")
        self.calculate_btn.bind(on_press=self.calculate_projectile)
        self.result_label = Label(text="")

        self.add_widget(layout)
        
        build_compact_calculator(
            self,
            layout,
            [
                ("Velocity (m/s)", self.velocity_input),
                ("Angle (deg)", self.angle_input),
                ("Range (m)", self.range_input),
                ("Max Height (m)", self.height_input),
                ("Time of Flight (s)", self.time_input),
            ],
            self.calculate_btn,
            self.result_label,
            "Projectile Motion",
            TOOL_COLORS["projectile"],
            "Solve for velocity, angle, range, height, or time.",
            result_height=120,
            button_text="Calculate Missing Values"
        )

    def calculate_projectile(self, instance):
        try:
            velocity = parse_optional_float(self.velocity_input.text)
            angle_deg = parse_optional_float(self.angle_input.text)
            range_ = parse_optional_float(self.range_input.text)
            max_height = parse_optional_float(self.height_input.text)
            time_of_flight = parse_optional_float(self.time_input.text)

            g = 9.81

            values = {
                "velocity": velocity,
                "angle": angle_deg,
                "range": range_,
                "height": max_height,
                "time": time_of_flight,
            }
            known = {k: v for k, v in values.items() if v is not None}

            if len(known) < 2:
                self.result_label.text = "⚠️ Enter at least TWO values — the rest will be solved."
                return

            # 1. Height <-> Time of flight
            if max_height is None and time_of_flight is not None:
                max_height = g * (time_of_flight ** 2) / 8
                known["height"] = max_height
            elif time_of_flight is None and max_height is not None and max_height >= 0:
                time_of_flight = math.sqrt(8 * max_height / g)
                known["time"] = time_of_flight

            # 2. Angle from H and R
            if angle_deg is None and max_height is not None and range_ is not None and range_ > 0:
                angle_rad = math.atan(4 * max_height / range_)
                angle_deg = math.degrees(angle_rad)
                known["angle"] = angle_deg

            # 3. Velocity from angle + one of {H, T, R}
            if velocity is None and angle_deg is not None:
                if max_height is not None and max_height > 0 and math.sin(math.radians(angle_deg)) != 0:
                    velocity = math.sqrt(2 * g * max_height) / math.sin(math.radians(angle_deg))
                elif time_of_flight is not None and math.sin(math.radians(angle_deg)) != 0:
                    velocity = time_of_flight * g / (2 * math.sin(math.radians(angle_deg)))
                elif range_ is not None and range_ > 0:
                    sin_2t = math.sin(2 * math.radians(angle_deg))
                    if sin_2t != 0:
                        velocity = math.sqrt(range_ * g / sin_2t)
                if velocity is not None:
                    known["velocity"] = velocity

            # 4. Angle from velocity + one of {H, T, R}
            if angle_deg is None and velocity is not None and velocity > 0:
                if max_height is not None and max_height > 0:
                    s = math.sqrt(2 * g * max_height) / velocity
                    if -1 <= s <= 1:
                        angle_deg = math.degrees(math.asin(s))
                elif time_of_flight is not None:
                    s = time_of_flight * g / (2 * velocity)
                    if -1 <= s <= 1:
                        angle_deg = math.degrees(math.asin(s))
                elif range_ is not None and range_ > 0:
                    s2 = range_ * g / (velocity ** 2)
                    if -1 <= s2 <= 1:
                        angle_deg = math.degrees(math.asin(s2) / 2)
                if angle_deg is not None:
                    known["angle"] = angle_deg

            # 5. Compute anything still missing from v & θ
            if velocity is not None and angle_deg is not None:
                angle_rad = math.radians(angle_deg)
                if range_ is None:
                    range_ = (velocity ** 2) * math.sin(2 * angle_rad) / g
                if max_height is None:
                    max_height = (velocity ** 2) * (math.sin(angle_rad) ** 2) / (2 * g)
                if time_of_flight is None:
                    time_of_flight = (2 * velocity * math.sin(angle_rad)) / g

            still_missing = [
                name for name, val in [
                    ("velocity", velocity),
                    ("angle", angle_deg),
                    ("range", range_),
                    ("height", max_height),
                    ("time", time_of_flight),
                ] if val is None
            ]
            if still_missing:
                self.result_label.text = (
                    "⚠️ Not enough information.\n"
                    f"Still unknown: {', '.join(still_missing)}"
                )
                return

            solved = []
            if values["velocity"] is None:
                solved.append(f"Initial Velocity: {velocity:.2f} m/s")
            if values["angle"] is None:
                solved.append(f"Launch Angle: {angle_deg:.2f}°")
            if values["range"] is None:
                solved.append(f"Range: {range_:.2f} m")
            if values["height"] is None:
                solved.append(f"Max Height: {max_height:.2f} m")
            if values["time"] is None:
                solved.append(f"Time of Flight: {time_of_flight:.2f} s")

            self.result_label.text = "\n".join(solved)

        except ValueError:
            self.result_label.text = "⚠️ Please enter valid numbers."



class NewtonLawsSimulator(Screen):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        layout = FloatLayout()

        self.mass_input = TextInput(multiline=False, input_filter='float')
        self.force_input = TextInput(multiline=False, input_filter='float')
        self.friction_input = TextInput(multiline=False, input_filter='float')
        self.accel_input = TextInput(multiline=False, input_filter='float')

        self.calculate_btn = Button(text="Calculate Missing Value")
        self.calculate_btn.bind(on_press=self.calculate_newton_laws)
        self.result_label = Label(text="")

        self.add_widget(layout)
        
        build_compact_calculator(
            self,
            layout,
            [
                ("Mass (kg)", self.mass_input),
                ("Applied Force (N)", self.force_input),
                ("Coefficient of Friction (μ)", self.friction_input),
                ("Acceleration (m/s²)", self.accel_input),
            ],
            self.calculate_btn,
            self.result_label,
            "Newton's Laws Simulator",
            TOOL_COLORS["newton"],
            "Solve for mass, force, friction, or acceleration.",
            rows=[
                [("Mass (kg)", self.mass_input), ("Applied Force (N)", self.force_input)],
                [("Coefficient of Friction (μ)", self.friction_input),
                 ("Acceleration (m/s²)", self.accel_input)],
            ],
            result_height=80,
            button_text="Calculate Missing Value"
        )

    def calculate_newton_laws(self, instance):
        try:
            mass = parse_optional_float(self.mass_input.text)
            applied_force = parse_optional_float(self.force_input.text)
            friction_coef = parse_optional_float(self.friction_input.text)
            acceleration = parse_optional_float(self.accel_input.text)

            g = 9.81

            values = {
                "mass": mass,
                "force": applied_force,
                "friction": friction_coef,
                "acceleration": acceleration,
            }
            missing = [k for k, v in values.items() if v is None]

            if len(missing) > 1:
                names = {
                    "mass": "Mass",
                    "force": "Applied Force",
                    "friction": "Coefficient of Friction",
                    "acceleration": "Acceleration",
                }
                self.result_label.text = (
                    "⚠️ Leave only ONE value blank.\n"
                    f"Currently blank: {', '.join(names[m] for m in missing)}"
                )
                return
            if len(missing) == 0:
                self.result_label.text = "⚠️ Leave exactly one field blank to solve for it."
                return

            target = missing[0]

            if target == "acceleration":
                if mass is None or mass <= 0:
                    self.result_label.text = "⚠️ Mass must be greater than 0."
                    return
                friction_force = friction_coef * mass * g
                net_force = applied_force - friction_force
                acceleration = 0.0 if net_force < 0 else net_force / mass
                self.result_label.text = f"Solved Acceleration: {acceleration:.2f} m/s²"
            elif target == "force":
                if mass is None or mass <= 0:
                    self.result_label.text = "⚠️ Mass must be greater than 0."
                    return
                friction_force = friction_coef * mass * g
                applied_force = mass * acceleration + friction_force
                self.result_label.text = f"Solved Applied Force: {applied_force:.2f} N"
            elif target == "friction":
                if mass is None or mass <= 0:
                    self.result_label.text = "⚠️ Mass must be greater than 0."
                    return
                friction_coef = (applied_force - mass * acceleration) / (mass * g)
                self.result_label.text = f"Solved Coefficient of Friction: {friction_coef:.3f}"
            elif target == "mass":
                denom = acceleration + friction_coef * g
                if denom == 0:
                    self.result_label.text = "⚠️ Cannot solve mass — denominator is 0."
                    return
                mass = applied_force / denom
                self.result_label.text = f"Solved Mass: {mass:.2f} kg"

        except ValueError:
            self.result_label.text = "⚠️ Please enter valid numbers."



class KinematicsSimulator(Screen):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        layout = FloatLayout()

        self.v0_input = TextInput(multiline=False, input_filter='float')
        self.a_input = TextInput(multiline=False, input_filter='float')
        self.t_input = TextInput(multiline=False, input_filter='float')
        self.s_input = TextInput(multiline=False, input_filter='float')
        self.v_input = TextInput(multiline=False, input_filter='float')

        self.calculate_btn = Button(text="Calculate Missing Values")
        self.calculate_btn.bind(on_press=self.calculate)
        self.result_label = Label(text="")

        self.add_widget(layout)

        build_compact_calculator(
            self,
            layout,
            [
                ("Initial Velocity v0 (m/s)", self.v0_input),
                ("Acceleration a (m/s²)", self.a_input),
                ("Time t (s)", self.t_input),
                ("Displacement s (m)", self.s_input),
                ("Final Velocity v (m/s)", self.v_input),
            ],
            self.calculate_btn,
            self.result_label,
            "Kinematics Simulator",
            TOOL_COLORS["kinematics"],
            "Solve for v0, a, t, s, or v.",
            rows=[
                [("Initial Velocity v0 (m/s)", self.v0_input),
                 ("Acceleration a (m/s²)", self.a_input)],
                [("Time t (s)", self.t_input),
                 ("Displacement s (m)", self.s_input),
                 ("Final Velocity v (m/s)", self.v_input)],
            ],
            result_height=120,
            button_text="Calculate Missing Values"
        )

    def calculate(self, instance):
        try:
            v0 = parse_optional_float(self.v0_input.text)
            a = parse_optional_float(self.a_input.text)
            t = parse_optional_float(self.t_input.text)
            s = parse_optional_float(self.s_input.text)
            v = parse_optional_float(self.v_input.text)

            values = {"v0": v0, "a": a, "t": t, "s": s, "v": v}
            was_blank = {k: (val is None) for k, val in values.items()}
            known_count = sum(1 for val in values.values() if val is not None)

            if known_count < 3:
                self.result_label.text = "⚠️ Enter at least THREE values — the rest will be solved."
                return

            # 1. v = v0 + a·t
            if v is None and v0 is not None and a is not None and t is not None:
                v = v0 + a * t
            if a is None and v is not None and v0 is not None and t is not None and t != 0:
                a = (v - v0) / t
            if t is None and v is not None and v0 is not None and a is not None and a != 0:
                t = (v - v0) / a
            if v0 is None and v is not None and a is not None and t is not None:
                v0 = v - a * t

            # 2. s = v0·t + ½·a·t²
            if s is None and v0 is not None and a is not None and t is not None:
                s = v0 * t + 0.5 * a * t ** 2
            if v0 is None and s is not None and a is not None and t is not None and t != 0:
                v0 = (s - 0.5 * a * t ** 2) / t
            if a is None and s is not None and v0 is not None and t is not None and t != 0:
                a = 2 * (s - v0 * t) / (t ** 2)

            # 3. v² = v0² + 2·a·s
            if v is None and v0 is not None and a is not None and s is not None:
                val = v0 ** 2 + 2 * a * s
                if val >= 0:
                    v = math.sqrt(val)
            if a is None and v is not None and v0 is not None and s is not None and s != 0:
                a = (v ** 2 - v0 ** 2) / (2 * s)
            if v0 is None and v is not None and a is not None and s is not None:
                val = v ** 2 - 2 * a * s
                if val >= 0:
                    v0 = math.sqrt(val)
            if s is None and v is not None and v0 is not None and a is not None and a != 0:
                s = (v ** 2 - v0 ** 2) / (2 * a)

            # 4. s = (v0 + v)/2 · t
            if s is None and v0 is not None and v is not None and t is not None:
                s = (v0 + v) / 2 * t
            if t is None and v0 is not None and v is not None and s is not None and (v0 + v) != 0:
                t = 2 * s / (v0 + v)
            if v0 is None and v is not None and s is not None and t is not None and t != 0:
                v0 = 2 * s / t - v
            if v is None and v0 is not None and s is not None and t is not None and t != 0:
                v = 2 * s / t - v0

            # 5. Retry a
            if a is None and v is not None and v0 is not None and t is not None and t != 0:
                a = (v - v0) / t

            # 6. Retry t
            if t is None and v is not None and v0 is not None and a is not None and a != 0:
                t = (v - v0) / a

            final = {"v0": v0, "a": a, "t": t, "s": s, "v": v}
            still_missing = [k for k, val in final.items() if val is None]
            if still_missing:
                self.result_label.text = (
                    "⚠️ Not enough information to solve everything.\n"
                    f"Still unknown: {', '.join(still_missing)}"
                )
                return

            solved = []
            if was_blank["v0"]:
                solved.append(f"Solved Initial Velocity v0: {v0:.2f} m/s")
            if was_blank["a"]:
                solved.append(f"Solved Acceleration a: {a:.2f} m/s²")
            if was_blank["t"]:
                solved.append(f"Solved Time t: {t:.2f} s")
            if was_blank["s"]:
                solved.append(f"Solved Displacement s: {s:.2f} m")
            if was_blank["v"]:
                solved.append(f"Solved Final Velocity v: {v:.2f} m/s")

            self.result_label.text = "\n".join(solved)

        except ValueError:
            self.result_label.text = "⚠️ Please enter valid numbers."



