class FormulaFlashcard(ButtonBehavior, BoxLayout):
    def __init__(self, formula, **kwargs):
        super().__init__(
            orientation='vertical',
            padding=12,
            spacing=5,
            size_hint_y=None,
            **kwargs
        )
        self.formula = formula
        self.revealed = False
        self.title_label = Label(
            text=f"[b]{formula['name']}[/b]",
            markup=True,
            font_size=17,
            color=TOOL_COLORS["formula_sheet"],
            size_hint=(1, None),
            height=30,
            halign='left',
            valign='middle'
        )
        self.title_label.bind(size=self.title_label.setter('text_size'))
        self.formula_label = Label(
            text=f"Formula: {formula['formula']}",
            font_size=16,
            color=(0.15, 0.2, 0.28, 1),
            size_hint=(1, None),
            height=0,
            opacity=0,
            halign='left',
            valign='middle'
        )
        self.explanation_label = Label(
            text=f"Explanation: {formula['explanation']}",
            font_size=13,
            color=(0.38, 0.45, 0.55, 1),
            size_hint=(1, None),
            height=0,
            opacity=0,
            halign='left',
            valign='middle'
        )
        self.units_label = Label(
            text=f"Units: {formula['units']}",
            font_size=12,
            color=(0.38, 0.45, 0.55, 1),
            size_hint=(1, None),
            height=0,
            opacity=0,
            halign='left',
            valign='middle'
        )
        self.hint_label = Label(
            text="Tap to reveal",
            font_size=12,
            color=TOOL_COLORS["formula_sheet"],
            size_hint=(1, None),
            height=22,
            halign='right',
            valign='middle'
        )
        for label in (
            self.formula_label,
            self.explanation_label,
            self.units_label,
            self.hint_label
        ):
            label.bind(size=label.setter('text_size'))

        with self.canvas.before:
            Color(1, 1, 1, 1)
            self.card_background = RoundedRectangle(
                pos=self.pos,
                size=self.size,
                radius=[14]
            )
        self.bind(
            pos=lambda widget, value: setattr(widget.card_background, 'pos', value),
            size=lambda widget, value: setattr(widget.card_background, 'size', value)
        )

        self.add_widget(self.title_label)
        self.add_widget(self.formula_label)
        self.add_widget(self.explanation_label)
        self.add_widget(self.units_label)
        self.add_widget(self.hint_label)
        self.update_card_height()

    def update_card_height(self):
        self.height = 12 * 2 + 5 * 4 + sum(
            label.height for label in (
                self.title_label,
                self.formula_label,
                self.explanation_label,
                self.units_label,
                self.hint_label
            )
        )

    def on_press(self):
        self.revealed = not self.revealed
        self.formula_label.height = 30 if self.revealed else 0
        self.explanation_label.height = 40 if self.revealed else 0
        self.units_label.height = 38 if self.revealed else 0
        self.formula_label.opacity = float(self.revealed)
        self.explanation_label.opacity = float(self.revealed)
        self.units_label.opacity = float(self.revealed)
        self.hint_label.text = "Tap to hide" if self.revealed else "Tap to reveal"
        self.update_card_height()


class FormulaSheet(Screen):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)

        main_layout = BoxLayout(orientation='vertical', padding=10, spacing=10)

        self.search_input = TextInput(
            hint_text="Search formulas...",
            size_hint=(1, None),
            height=40,
            multiline=False
        )
        self.search_input.bind(text=self.on_search_text)
        self.search_input.background_normal = ''
        self.search_input.background_active = ''
        self.search_input.background_color = (1, 1, 1, 1)
        self.search_input.foreground_color = (0.15, 0.2, 0.28, 1)
        self.search_input.cursor_color = TOOL_COLORS["formula_sheet"]
        self.search_input.padding = [12, 10]

        self.scrollview = ScrollView(size_hint=(1, 1))
        self.formula_list = GridLayout(cols=1, spacing=10, size_hint_y=None)
        self.formula_list.bind(minimum_height=self.formula_list.setter('height'))
        self.scrollview.add_widget(self.formula_list)

        main_layout.add_widget(self.scrollview)
        main_layout.add_widget(self.search_input)

        self.add_widget(main_layout)
        with self.canvas.before:
            Color(0.96, 0.97, 0.99, 1)
            self.background = Rectangle(pos=self.pos, size=self.size)
        self.bind(
            pos=lambda widget, value: setattr(self.background, 'pos', value),
            size=lambda widget, value: setattr(self.background, 'size', value)
        )

        add_tool_header(
            self,
            main_layout,
            "Physics Formula Sheet",
            TOOL_COLORS["formula_sheet"],
            "Browse and search essential physics equations."
        )

        self.display_formulas(FORMULAS)

    def display_formulas(self, formulas):
        self.formula_list.clear_widgets()
        if not formulas:
            self.formula_list.add_widget(Label(
                text="No formulas found.",
                size_hint_y=None,
                height=30,
                color=(0.38, 0.45, 0.55, 1)
            ))
            return
        for formula in formulas:
            self.formula_list.add_widget(FormulaFlashcard(formula))

    def on_search_text(self, instance, value):
        query = value.lower().strip()
        if not query:
            filtered = FORMULAS
        else:
            filtered = [
                f for f in FORMULAS
                if query in f['name'].lower() or
                   query in f['formula'].lower() or
                   query in f['explanation'].lower()
            ]
        self.display_formulas(filtered)



